-- Agent judgments are durable data; infrastructure enforces facts and recovery.
SET ROLE hub2_v8_owner;
ALTER TABLE v8.context_manifests ADD COLUMN canonical_text text;
UPDATE v8.context_manifests SET canonical_text=v8.canonical_json(manifest) WHERE encode(public.digest(v8.canonical_json(manifest),'sha256'),'hex')=sha256;
ALTER TABLE v8.adoptions ADD COLUMN use_evidence jsonb NOT NULL DEFAULT '{}';
ALTER TABLE v8.handoffs ADD COLUMN event_revision bigint NOT NULL DEFAULT 1;UPDATE v8.handoffs SET event_revision=CASE state WHEN 'continued' THEN 3 WHEN 'accepted' THEN 2 WHEN 'declined' THEN 2 ELSE 1 END;
ALTER TABLE v8.context_views ADD COLUMN expires_at timestamptz NOT NULL DEFAULT (clock_timestamp()+interval '15 minutes');
ALTER TABLE v8.work_items ADD COLUMN related_assessment text NOT NULL DEFAULT 'unassessed' CHECK(related_assessment IN ('assessed','partial','unassessed'));
ALTER TABLE v8.work_items ADD COLUMN pending_enrichment jsonb NOT NULL DEFAULT '[]';
UPDATE v8.work_items SET related_assessment='assessed' WHERE related_evaluated;
CREATE TABLE v8.work_updates(id uuid PRIMARY KEY,work_item_id uuid NOT NULL REFERENCES v8.work_items(id),work_revision bigint NOT NULL,actor_id uuid NOT NULL,client_id uuid NOT NULL,source_context_id uuid,payload jsonb NOT NULL,canonical_text text NOT NULL,sha256 text NOT NULL CHECK(sha256~'^[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE v8.work_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),work_item_id uuid NOT NULL REFERENCES v8.work_items(id),work_revision bigint NOT NULL,record jsonb NOT NULL,canonical_text text NOT NULL,sha256 text NOT NULL CHECK(sha256~'^[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(work_item_id,work_revision));
CREATE TABLE v8.impact_judgments(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES v8.projects(id),work_item_id uuid REFERENCES v8.work_items(id),context_id uuid REFERENCES v8.context_manifests(id),actor_id uuid NOT NULL,client_id uuid NOT NULL,source_context_id uuid,choice text NOT NULL,applicable_scope jsonb NOT NULL,reason jsonb,payload jsonb NOT NULL,canonical_text text NOT NULL,sha256 text NOT NULL CHECK(sha256~'^[0-9a-f]{64}$'),supersedes uuid REFERENCES v8.impact_judgments(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
REVOKE ALL ON v8.work_updates,v8.work_snapshots,v8.impact_judgments FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;
CREATE OR REPLACE FUNCTION v8.assert_ref(c jsonb,ref jsonb) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,v8 AS $$ BEGIN PERFORM mem.assert_version_sources((c->>'handle_id')::uuid,(ref->>'version_id')::uuid,'mem.read');
 IF NOT EXISTS(SELECT 1 FROM mem.content_versions cv JOIN mem.materials m ON m.id=cv.material_id JOIN mem.verified_objects verified ON verified.id=cv.object_id AND verified.sha256=cv.sha256 AND verified.size=cv.size WHERE cv.id=(ref->>'version_id')::uuid AND cv.material_id=(ref->>'material_id')::uuid AND cv.sha256=ref->>'sha256' AND m.state='active' ) OR NOT mem.version_visible((c->>'actor_id')::uuid,(ref->>'version_id')::uuid) THEN RAISE EXCEPTION 'fixed_ref_forbidden' USING ERRCODE='42501';END IF;END $$;
CREATE FUNCTION v8.reference_facts(ref jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,v8 AS $$
 SELECT jsonb_build_object('material_id',cv.material_id,'version_id',cv.id,'sha256',cv.sha256,'registry_hash_verified',true,'artifact_availability',obj.availability,'provenance_state',cv.provenance_state,'byte_delivery','not_asserted') FROM mem.content_versions cv JOIN mem.verified_objects obj ON obj.id=cv.object_id AND obj.sha256=cv.sha256 AND obj.size=cv.size WHERE cv.id=(ref->>'version_id')::uuid AND cv.material_id=(ref->>'material_id')::uuid AND cv.sha256=ref->>'sha256' $$;
CREATE FUNCTION v8.manager_options(c jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,v8 AS $$ SELECT COALESCE(jsonb_agg(jsonb_build_object('manager_id',id,'label',display_name,'basis','current_organization_admin') ORDER BY display_name,id),'[]') FROM authz.principals WHERE organization_id=(c->>'organization_id')::uuid AND role='organization_admin' AND active $$;
CREATE FUNCTION v8.select_manager(c jsonb,selected uuid) RETURNS uuid LANGUAGE plpgsql SET search_path=pg_catalog,v8 AS $$ DECLARE result uuid; options jsonb;BEGIN
 IF selected IS NOT NULL THEN SELECT id INTO result FROM authz.principals WHERE id=selected AND organization_id=(c->>'organization_id')::uuid AND active AND role='organization_admin';IF result IS NULL THEN RAISE EXCEPTION 'invalid_organization_manager' USING ERRCODE='42501';END IF;RETURN result;END IF;
 SELECT id INTO result FROM authz.principals WHERE id=(c->>'actor_id')::uuid AND role='organization_admin' AND active;IF result IS NOT NULL THEN RETURN result;END IF;
 options:=v8.manager_options(c);IF jsonb_array_length(options)=1 THEN RETURN (options->0->>'manager_id')::uuid;END IF;RETURN NULL;
END $$;
CREATE FUNCTION v8.authorized_ref(h uuid,c jsonb,ref jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog,v8 AS $$ BEGIN IF NOT mem.version_visible((c->>'actor_id')::uuid,(ref->>'version_id')::uuid) THEN RETURN false;END IF;BEGIN PERFORM mem.assert_version_sources(h,(ref->>'version_id')::uuid,'mem.read');EXCEPTION WHEN insufficient_privilege THEN RETURN false;END;RETURN true;END $$;
CREATE FUNCTION v8.ref_inputs(p_explanation jsonb) RETURNS SETOF jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,v8 AS $$ SELECT DISTINCT value FROM jsonb_path_query(p_explanation,'$.**') value WHERE jsonb_typeof(value)='object' AND value ? 'material_id' AND value ? 'version_id' AND value ? 'sha256' $$;
CREATE FUNCTION v8.authorized_statement(h uuid,c jsonb,statement jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog,v8 AS $$ DECLARE ref jsonb;BEGIN FOR ref IN SELECT value FROM v8.ref_inputs(statement) AS input(value) LOOP IF NOT v8.authorized_ref(h,c,ref) THEN RETURN false;END IF;END LOOP;RETURN true;END $$;
CREATE FUNCTION v8.build_context(h uuid,c jsonb,w v8.work_items,config jsonb,o uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,v8 AS $$
DECLARE pr v8.projects;ref jsonb;item jsonb;refs jsonb;cid uuid:=gen_random_uuid();expiry timestamptz;manifest jsonb;hash text;pending jsonb:='[]';evidence jsonb;raw_refs jsonb;restricted_narrative boolean:=false;BEGIN
 SELECT * INTO pr FROM v8.projects WHERE id=w.project_id;IF config->>'refreshes_context_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM v8.context_manifests WHERE id=(config->>'refreshes_context_id')::uuid AND work_item_id=w.id AND project_id=w.project_id) THEN RAISE EXCEPTION 'refresh_context_scope_mismatch' USING ERRCODE='42501';END IF;
 raw_refs:=COALESCE(config->'fixed_refs',(SELECT COALESCE(jsonb_agg(DISTINCT jsonb_build_object('material_id',material_id,'version_id',version_id,'sha256',sha256,'role',role)),'[]') FROM v8.results WHERE work_item_id=w.id));
 refs:='[]';FOR ref IN SELECT value FROM jsonb_array_elements(raw_refs) LOOP IF config ? 'fixed_refs' THEN PERFORM v8.assert_ref(c,ref);refs:=refs||jsonb_build_array(ref);ELSIF v8.authorized_ref(h,c,ref) THEN PERFORM v8.assert_ref(c,ref);refs:=refs||jsonb_build_array(ref);ELSE restricted_narrative:=true;END IF;END LOOP;FOR ref IN SELECT value FROM v8.ref_inputs(w.explanation) AS input(value) LOOP IF NOT v8.authorized_ref(h,c,ref) THEN restricted_narrative:=true;END IF;END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(COALESCE(config->'effective_decisions','[]')||COALESCE(config->'dissenting_views','[]')||COALESCE(config->'rejected_explanations','[]')) LOOP
 IF item ? 'reason_ref' THEN ref:=item->'reason_ref';PERFORM v8.assert_ref(c,ref);IF NOT EXISTS(SELECT FROM jsonb_array_elements(refs) existing WHERE existing->>'version_id'=ref->>'version_id' AND existing->>'material_id'=ref->>'material_id') THEN refs:=refs||jsonb_build_array(ref||jsonb_build_object('role','reason'));END IF;END IF;END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(COALESCE(config->'pending_operations','[]')) LOOP
 SELECT result INTO evidence FROM v8.operations WHERE id=(item->>'operation_id')::uuid AND actor_id=(c->>'actor_id')::uuid AND project_id=w.project_id;
 IF evidence IS NULL THEN evidence:=mem.operation_evidence((c->>'actor_id')::uuid,w.project_id,(item->>'operation_id')::uuid);END IF;
 pending:=pending||jsonb_build_array(item||jsonb_build_object('evidence_state',CASE WHEN evidence IS NULL THEN 'agent_declared_not_verified' ELSE 'service_receipt' END,'actual_receipt',evidence));END LOOP;
 expiry:=clock_timestamp()+make_interval(secs=>LEAST(GREATEST(COALESCE((config->>'ttl_seconds')::integer,900),30),900));
 manifest:=jsonb_build_object('properties',COALESCE(config->'properties','{}'),'agent_metadata',config-'idempotency_key'-'project_id'-'work_item_id'-'expected_work_revision')||jsonb_build_object('schema_version','context.v2','context_id',cid,'project_id',w.project_id,'project_revision',pr.revision,'project_epoch',pr.epoch,'work_item_id',w.id,'work_revision',w.revision,'snapshot_watermark',w.event_revision,'goal',w.goal,'summary',CASE WHEN restricted_narrative THEN NULL ELSE w.description END,'explanation',CASE WHEN restricted_narrative THEN NULL ELSE w.explanation END,'related_assessment',w.related_assessment,'pending_enrichment',w.pending_enrichment,'effective_decisions',COALESCE(config->'effective_decisions','[]'),'dissenting_views',COALESCE(config->'dissenting_views','[]'),'rejected_explanations',COALESCE(config->'rejected_explanations','[]'),'fixed_refs',refs,'limitations',COALESCE(config->'limitations','[]'),'pending_operations',pending,'next_steps',COALESCE(config->'next_steps',CASE WHEN restricted_narrative THEN '[]'::jsonb ELSE w.explanation->'next_steps' END,'[]'),'judgments',COALESCE(config->'judgments','{}'),'source_coverage',COALESCE(config->>'source_coverage','unknown'),'coverage',jsonb_build_object('complete',COALESCE(config->'complete','false')='true'::jsonb AND NOT restricted_narrative,'inherited_narrative',CASE WHEN restricted_narrative THEN 'restricted_and_omitted' ELSE 'current_authorized' END,'host_visible','unknown'),'created_at',clock_timestamp(),'expires_at',expiry,'source_context_id',c->'source_context_id','trust','agent_declarations_and_source_material_not_execution_authority');
 hash:=encode(public.digest(v8.canonical_json(manifest),'sha256'),'hex');PERFORM authz.assert_effect(h);
 INSERT INTO v8.context_manifests(id,project_id,work_item_id,work_revision,actor_id,source_context_id,manifest,canonical_text,sha256,source_coverage,expires_at,refreshes_context_id) VALUES(cid,w.project_id,w.id,w.revision,(c->>'actor_id')::uuid,(c->>'source_context_id')::uuid,manifest,v8.canonical_json(manifest),hash,COALESCE(config->>'source_coverage','unknown'),expiry,(config->>'refreshes_context_id')::uuid);
 FOR ref IN SELECT value FROM jsonb_array_elements(refs) LOOP INSERT INTO v8.context_sources(context_id,material_id,version_id,sha256,role) VALUES(cid,(ref->>'material_id')::uuid,(ref->>'version_id')::uuid,ref->>'sha256',COALESCE(ref->>'role','input')) ON CONFLICT DO NOTHING;END LOOP;
 PERFORM v8.emit(c,'context.prepared',cid,1,o,jsonb_build_object('manifest_hash',hash,'work_item_id',w.id));RETURN jsonb_build_object('context_id',cid,'manifest_hash',hash,'expires_at',expiry,'coverage',manifest->'coverage');
END $$;
CREATE FUNCTION v8.write_work(h uuid,d text,b jsonb,c jsonb,command text,allow_create boolean) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,v8 AS $$
DECLARE r jsonb;o uuid:=gen_random_uuid();w v8.work_items;target v8.work_items;ref jsonb;rel jsonb;basis jsonb;delivery jsonb;source jsonb;outputs jsonb;facts jsonb;artifacts jsonb:='[]';warnings jsonb:='[]';assessment text;enrichment jsonb:='[]';claim text;is_new boolean:=false;mode text;note jsonb;prior jsonb;hash text;context_result jsonb:='{}';BEGIN
 r:=v8.replay(c,command,b,d);IF r IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN r;END IF;
 IF b->>'work_item_id' IS NULL THEN
  IF NOT allow_create THEN RAISE EXCEPTION 'work_item_required';END IF;is_new:=true;PERFORM authz.assert_effect(h);
  INSERT INTO v8.work_items(id,project_id,actor_id,client_id,source_context_id,goal,description) VALUES(gen_random_uuid(),(c->>'project_id')::uuid,(c->>'actor_id')::uuid,(c->>'client_id')::uuid,(c->>'source_context_id')::uuid,COALESCE(b->>'goal',b->>'summary','目标尚未说明'),COALESCE(b->>'description','')) RETURNING * INTO w;
  INSERT INTO v8.work_executions(work_item_id,actor_id,client_id,source_context_id) VALUES(w.id,w.actor_id,w.client_id,w.source_context_id);
 ELSE w:=v8.lock_work(c,(b->>'work_item_id')::uuid);END IF;
 IF b->>'expected_revision' IS NOT NULL AND w.revision<>(b->>'expected_revision')::bigint THEN RETURN v8.remember(c,command,b,d,o,jsonb_build_object('state','conflict','domain_revision',w.revision,'error_code','revision_conflict','candidate',b,'retained_state','candidate_and_originals_preserved','next_step','compare_current_updates_or_rebase'));END IF;
 mode:=CASE WHEN is_new OR b->>'expected_revision' IS NOT NULL THEN 'cas' ELSE 'append_only' END;
 IF mode='cas' AND NOT is_new THEN prior:=to_jsonb(w)||jsonb_build_object('fixed_refs',(SELECT COALESCE(jsonb_agg(jsonb_build_object('material_id',material_id,'version_id',version_id,'sha256',sha256,'role',role)),'[]') FROM v8.results WHERE work_item_id=w.id));PERFORM authz.assert_effect(h);INSERT INTO v8.work_snapshots(work_item_id,work_revision,record,canonical_text,sha256) VALUES(w.id,w.revision,prior,v8.canonical_json(prior),encode(public.digest(v8.canonical_json(prior),'sha256'),'hex')) ON CONFLICT DO NOTHING;END IF;
 outputs:=COALESCE(b->'outputs','[]');assessment:=COALESCE(b->>'related_assessment',CASE WHEN b->'related_evaluated'='true'::jsonb THEN 'assessed' ELSE 'unassessed' END);IF assessment NOT IN('assessed','partial','unassessed') THEN RAISE EXCEPTION 'invalid_assessment_state';END IF;
 claim:=COALESCE(b->>'completion_state',CASE WHEN command='work_commit' THEN 'completed' ELSE 'in_progress' END);IF claim NOT IN('open','in_progress','completed','cancelled') THEN RAISE EXCEPTION 'invalid_completion_claim';END IF;
 IF b->'explanation' IS NULL OR b->'explanation'='{}'::jsonb THEN enrichment:=enrichment||jsonb_build_array('explanation');END IF;IF assessment<>'assessed' THEN enrichment:=enrichment||jsonb_build_array('relationship_assessment');END IF;IF COALESCE(b->>'goal','')='' AND is_new THEN enrichment:=enrichment||jsonb_build_array('goal');END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(outputs) LOOP PERFORM v8.assert_ref(c,ref);facts:=v8.reference_facts(ref);artifacts:=artifacts||jsonb_build_array(facts);IF facts->>'artifact_availability'<>'available' THEN IF NOT enrichment ? 'artifact_availability' THEN enrichment:=enrichment||jsonb_build_array('artifact_availability');END IF;warnings:=warnings||jsonb_build_array(jsonb_build_object('code','fixed_artifact_current_bytes_unavailable','version_id',ref->'version_id','artifact_availability',facts->'artifact_availability','next_step','agent_may_use_known_copy_or_restore_object_without_changing_fixed_reference'));END IF;IF EXISTS(SELECT 1 FROM mem.content_versions WHERE id=(ref->>'version_id')::uuid AND provenance_state='pending') AND NOT enrichment ? 'source_provenance' THEN enrichment:=enrichment||jsonb_build_array('source_provenance');END IF;PERFORM authz.assert_effect(h);INSERT INTO v8.results(work_item_id,material_id,version_id,sha256,role,explanation,created_by) VALUES(w.id,(ref->>'material_id')::uuid,(ref->>'version_id')::uuid,ref->>'sha256',COALESCE(ref->>'role','result'),COALESCE(b->'explanation','{}'),(c->>'actor_id')::uuid);END LOOP;
 FOR ref IN SELECT value FROM v8.ref_inputs(b->'explanation') AS input(value) LOOP PERFORM v8.assert_ref(c,ref);END LOOP;
 FOR rel IN SELECT value FROM jsonb_array_elements(COALESCE(b->'related','[]')) LOOP
  SELECT * INTO target FROM v8.work_items WHERE id=(rel->>'work_item_id')::uuid;
  IF target.id IS NULL OR target.id=w.id OR NOT authz.can_read((c->>'actor_id')::uuid,target.project_id) THEN RAISE EXCEPTION 'relation_target_forbidden' USING ERRCODE='42501';END IF;
  basis:=COALESCE(rel->'basis','{}');delivery:=jsonb_build_object('declared_use',COALESCE(basis->>'use_origin','agent_declared'),'work_delivery',CASE WHEN basis->>'work_read_receipt_id' IS NULL THEN 'not_provided' WHEN EXISTS(SELECT 1 FROM v8.work_read_receipts receipt WHERE receipt.id=(basis->>'work_read_receipt_id')::uuid AND receipt.actor_id=(c->>'actor_id')::uuid AND receipt.client_id=(c->>'client_id')::uuid AND receipt.work_item_id=target.id AND receipt.state IN('sent','acknowledged')) THEN 'verified_service_delivery' ELSE 'unverified_claim' END,'ref_deliveries','[]'::jsonb);
  FOR source IN SELECT value FROM jsonb_array_elements(COALESCE(basis->'refs','[]')) LOOP ref:=COALESCE(source->'fixed_ref',source);PERFORM v8.assert_ref(c,ref);delivery:=jsonb_set(delivery,'{ref_deliveries}',(delivery->'ref_deliveries')||jsonb_build_array(jsonb_build_object('version_id',ref->'version_id','service_delivery',CASE WHEN source->>'read_receipt_id' IS NULL THEN 'not_provided' WHEN mem.delivered_ref((c->>'actor_id')::uuid,(c->>'client_id')::uuid,(source->>'read_receipt_id')::uuid,(ref->>'material_id')::uuid,(ref->>'version_id')::uuid,ref->>'sha256') THEN 'verified' ELSE 'unverified_claim' END)));END LOOP;
  IF rel ? 'supersedes' AND NOT EXISTS(SELECT 1 FROM v8.work_relations WHERE id=(rel->>'supersedes')::uuid AND ((from_work_id=w.id AND to_work_id=target.id) OR (to_work_id=w.id AND from_work_id=target.id))) THEN RAISE EXCEPTION 'invalid_relation_correction';END IF;
  PERFORM authz.assert_effect(h);INSERT INTO v8.work_relations(from_work_id,to_work_id,basis,actor_id,source_context_id,supersedes,state) VALUES(w.id,target.id,basis||jsonb_build_object('infrastructure_evidence',delivery),(c->>'actor_id')::uuid,(c->>'source_context_id')::uuid,(rel->>'supersedes')::uuid,COALESCE(rel->>'state','active'));
 END LOOP;
 note:=b-'idempotency_key'||jsonb_build_object('completion_claim',claim,'related_assessment',assessment,'pending_enrichment',enrichment,'write_mode',mode,'previous_revision',w.revision);
 hash:=encode(public.digest(v8.canonical_json(note),'sha256'),'hex');PERFORM authz.assert_effect(h);
 UPDATE v8.work_items SET description=CASE WHEN mode='cas' THEN COALESCE(b->>'summary',description) ELSE description END,explanation=CASE WHEN mode='cas' THEN COALESCE(b->'explanation',explanation) ELSE explanation END,goal=CASE WHEN mode='cas' THEN COALESCE(b->>'goal',goal) ELSE goal END,state=CASE WHEN mode='cas' THEN claim ELSE state END,related_assessment=CASE WHEN mode='cas' THEN assessment ELSE related_assessment END,related_evaluated=CASE WHEN mode='cas' THEN assessment='assessed' ELSE related_evaluated END,pending_enrichment=CASE WHEN mode='cas' THEN enrichment ELSE pending_enrichment END,completed_receipt_id=CASE WHEN mode='cas' AND claim='completed' THEN o ELSE completed_receipt_id END,revision=revision+1,event_revision=event_revision+1,updated_at=clock_timestamp() WHERE id=w.id RETURNING * INTO w;
 INSERT INTO v8.work_updates(id,work_item_id,work_revision,actor_id,client_id,source_context_id,payload,canonical_text,sha256) VALUES(o,w.id,w.revision,(c->>'actor_id')::uuid,(c->>'client_id')::uuid,(c->>'source_context_id')::uuid,note,v8.canonical_json(note),hash);
 IF b ? 'context' AND b->'context'<>'false'::jsonb THEN context_result:=v8.build_context(h,c,w,CASE WHEN jsonb_typeof(b->'context')='object' THEN b->'context' ELSE '{}'::jsonb END,o);END IF;
 PERFORM v8.emit(c,'work.recorded',w.id,w.event_revision,o,jsonb_build_object('work_revision',w.revision,'update_id',o,'update_hash',hash,'completion_claim',claim));
 r:=jsonb_build_object('state',CASE WHEN command='work_commit' THEN claim ELSE 'saved' END,'work_item_id',w.id,'short_no',w.short_no,'domain_revision',w.revision,'fixed_refs',outputs,'artifact_availability',artifacts,'warnings',warnings,'completion_claim',claim,'related_assessment',assessment,'pending_enrichment',enrichment,'update_id',o,'update_hash',hash,'write_mode',mode,'receipt',jsonb_build_object('receipt_id',o,'registration','committed','fixed_reference_integrity','verified_registry_identity','current_byte_delivery','not_asserted','completion','agent_declared','quality','agent_judgment','external_execution','not_asserted','formal_completion',claim='completed','statement_hash',hash))||context_result;
 RETURN v8.remember(c,command,b,d,o,r);
END $$;

CREATE OR REPLACE FUNCTION v8.work_commit(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;o uuid:=gen_random_uuid(); BEGIN
 IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.work.commit',d,b);
 RETURN v8.write_work(h,d,b,c,'work_commit',false);
END $$;
GRANT EXECUTE ON FUNCTION v8.work_commit(uuid,text,text) TO hub2_v8;

CREATE OR REPLACE FUNCTION v8.work_save(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;o uuid:=gen_random_uuid(); BEGIN
 IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.work.commit',d,b);
 RETURN v8.write_work(h,d,b,c,'work_save',true);
END $$;
GRANT EXECUTE ON FUNCTION v8.work_save(uuid,text,text) TO hub2_v8;

CREATE OR REPLACE FUNCTION v8.context_prepare(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;o uuid:=gen_random_uuid();w v8.work_items; BEGIN
 IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.context.prepare',d,b);
 r:=v8.replay(c,'context_prepare',b,d);IF r IS NOT NULL THEN RETURN r;END IF;w:=v8.lock_work(c,(b->>'work_item_id')::uuid);IF b->>'expected_work_revision' IS NOT NULL AND w.revision<>(b->>'expected_work_revision')::bigint THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001';END IF;r:=v8.build_context(h,c,w,b,o);RETURN v8.remember(c,'context_prepare',b,d,o,jsonb_build_object('state','prepared','domain_revision',w.revision)||r);
END $$;
GRANT EXECUTE ON FUNCTION v8.context_prepare(uuid,text,text) TO hub2_v8;

CREATE OR REPLACE FUNCTION v8.manager_candidates(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;o uuid:=gen_random_uuid(); BEGIN
 IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.project.create',d,b);
 RETURN jsonb_build_object('state','available_candidates','items',v8.manager_options(c),'coverage','current_organization_manager_sources','next_step','agent_selects_effective_manager');
END $$;
GRANT EXECUTE ON FUNCTION v8.manager_candidates(uuid,text,text) TO hub2_v8;
CREATE OR REPLACE FUNCTION v8.project_create(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$
DECLARE b jsonb; c jsonb; r jsonb; o uuid:=gen_random_uuid(); pr v8.projects;manager uuid;
BEGIN
 IF encode(public.digest(p,'sha256'),'hex')<>d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF;
 b:=p::jsonb;c:=v8.guard(h,'v8.project.create',d,b);
 r:=v8.replay(c,'project_create',b,d);IF r IS NOT NULL THEN RETURN r;END IF;
 IF (b->>'owner_id')::uuid IS DISTINCT FROM (c->>'actor_id')::uuid OR (b->>'organization_id')::uuid IS DISTINCT FROM (c->>'organization_id')::uuid THEN RAISE EXCEPTION 'identity_override' USING ERRCODE='42501';END IF;
 manager:=(c->>'actor_id')::uuid;
 IF b->>'visibility'='team' THEN manager:=v8.select_manager(c,(b->>'manager_id')::uuid);IF manager IS NULL THEN RETURN jsonb_build_object('state','manager_selection_required','project_id',c->'project_id','items',v8.manager_options(c),'retained_state','not_created','next_step','agent_selects_effective_manager_and_retries');END IF;END IF;
 PERFORM authz.assert_effect(h);INSERT INTO v8.projects(id,organization_id,kind,visibility,owner_id,manager_id,title) VALUES((c->>'project_id')::uuid,(c->>'organization_id')::uuid,b->>'kind',b->>'visibility',(c->>'actor_id')::uuid,manager,b->>'title') RETURNING * INTO pr;
 IF pr.visibility='team' THEN PERFORM authz.project_scope_transition(c,pr.id,pr.revision,pr.visibility,pr.kind,pr.manager_id);END IF;
 PERFORM v8.emit(c,'project.created',pr.id,1,o,jsonb_build_object('kind',pr.kind,'visibility',pr.visibility));RETURN v8.remember(c,'project_create',b,d,o,jsonb_build_object('state','created','project',to_jsonb(pr),'domain_revision',pr.revision));
END $$;
CREATE OR REPLACE FUNCTION v8.project_convert(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$
DECLARE b jsonb; c jsonb; r jsonb; o uuid:=gen_random_uuid(); pr v8.projects;manager uuid;
BEGIN
 IF encode(public.digest(p,'sha256'),'hex')<>d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF;
 b:=p::jsonb;c:=v8.guard(h,'v8.project.convert',d,b);
 r:=v8.replay(c,'project_convert',b,d);IF r IS NOT NULL THEN RETURN r;END IF;
 SELECT * INTO pr FROM v8.projects WHERE id=(c->>'project_id')::uuid;manager:=CASE WHEN b->>'visibility'='team' THEN COALESCE((b->>'manager_id')::uuid,CASE WHEN pr.visibility='team' THEN pr.manager_id ELSE v8.select_manager(c,NULL) END) ELSE pr.owner_id END;
 IF manager IS NULL THEN RETURN jsonb_build_object('state','manager_selection_required','items',v8.manager_options(c),'retained_state','scope_unchanged','next_step','agent_selects_effective_manager_and_retries');END IF;PERFORM authz.assert_effect(h);r:=authz.project_scope_transition(c,(c->>'project_id')::uuid,(b->>'expected_revision')::bigint,b->>'visibility',b->>'kind',manager);
 SELECT * INTO pr FROM v8.projects WHERE id=(c->>'project_id')::uuid FOR UPDATE;
 UPDATE v8.projects SET visibility=b->>'visibility',kind=b->>'kind',manager_id=(r->>'manager_id')::uuid,revision=revision+1,epoch=epoch+1,event_revision=event_revision+1 WHERE id=pr.id RETURNING * INTO pr;
 PERFORM v8.emit(c,'project.scope_changed',pr.id,pr.event_revision,o,jsonb_build_object('revision',pr.revision,'visibility',pr.visibility,'kind',pr.kind,'agent_reason',b->'reason','agent_judgment',b->'judgment'));RETURN v8.remember(c,'project_convert',b,d,o,jsonb_build_object('state','converted','project',to_jsonb(pr),'domain_revision',pr.revision));
END $$;
CREATE OR REPLACE FUNCTION v8.adoption_set(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$
DECLARE b jsonb; c jsonb; r jsonb; o uuid:=gen_random_uuid(); w v8.work_items;old v8.adoptions;adopted v8.adoptions;ref jsonb;
BEGIN
 IF encode(public.digest(p,'sha256'),'hex')<>d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF;
 b:=p::jsonb;c:=v8.guard(h,'v8.adoption.set',d,b);
 r:=v8.replay(c,'adoption_set',b,d);IF r IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN r;END IF;w:=v8.lock_work(c,(b->>'work_item_id')::uuid);
 SELECT * INTO old FROM v8.adoptions WHERE work_item_id=w.id AND role=COALESCE(b->>'role','adopted') ORDER BY revision DESC LIMIT 1;
 IF (b->>'expected_work_revision' IS NOT NULL AND w.revision<>(b->>'expected_work_revision')::bigint) OR COALESCE(old.revision,0)<>COALESCE((b->>'expected_adoption_revision')::bigint,0) THEN PERFORM authz.assert_effect(h);RETURN v8.remember(c,'adoption_set',b,d,o,jsonb_build_object('state','conflict','domain_revision',w.revision,'adoption_revision',COALESCE(old.revision,0),'error_code','revision_conflict','retained_state','published_candidate_and_reason_preserved','next_step','explicit_rebase'));END IF;
 ref:=b->'fixed_ref';PERFORM v8.assert_ref(c,ref);
 PERFORM authz.assert_effect(h);INSERT INTO v8.adoptions(work_item_id,material_id,version_id,sha256,role,reason,revision,actor_id,source_context_id,supersedes,use_evidence) VALUES(w.id,(ref->>'material_id')::uuid,(ref->>'version_id')::uuid,ref->>'sha256',COALESCE(b->>'role','adopted'),COALESCE(b->>'reason',''),COALESCE(old.revision,0)+1,(c->>'actor_id')::uuid,(c->>'source_context_id')::uuid,old.id,jsonb_build_object('declared_use',COALESCE(b->>'use_origin','agent_declared'),'judgment',COALESCE(b->'judgment','{}'),'service_delivery',CASE WHEN b->>'read_receipt_id' IS NULL THEN 'not_provided' WHEN mem.delivered_ref((c->>'actor_id')::uuid,(c->>'client_id')::uuid,(b->>'read_receipt_id')::uuid,(ref->>'material_id')::uuid,(ref->>'version_id')::uuid,ref->>'sha256') THEN 'verified' ELSE 'unverified_claim' END)) RETURNING * INTO adopted;
 PERFORM authz.assert_effect(h);UPDATE v8.work_items SET revision=revision+1,event_revision=event_revision+1,updated_at=clock_timestamp() WHERE id=w.id RETURNING * INTO w;
 PERFORM v8.emit(c,'adoption.changed',w.id,w.event_revision,o,jsonb_build_object('adoption_id',adopted.id,'revision',adopted.revision,'fixed_ref',ref));PERFORM authz.assert_effect(h);RETURN v8.remember(c,'adoption_set',b,d,o,jsonb_build_object('state','adopted','adoption_id',adopted.id,'adoption_revision',adopted.revision,'domain_revision',w.revision,'fixed_refs',jsonb_build_array(ref),'artifact_availability',jsonb_build_array(v8.reference_facts(ref)),'use_evidence',jsonb_build_object('declared_use',COALESCE(b->>'use_origin','agent_declared'),'judgment',COALESCE(b->'judgment','{}'),'service_delivery',CASE WHEN b->>'read_receipt_id' IS NULL THEN 'not_provided' WHEN mem.delivered_ref((c->>'actor_id')::uuid,(c->>'client_id')::uuid,(b->>'read_receipt_id')::uuid,(ref->>'material_id')::uuid,(ref->>'version_id')::uuid,ref->>'sha256') THEN 'verified' ELSE 'unverified_claim' END)));
END $$;


CREATE FUNCTION v8.render_current_view(h uuid,c jsonb,ctx v8.context_manifests,mode text,o uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,v8 AS $$
DECLARE w v8.work_items;pr v8.projects;source record;refs jsonb:='[]';warnings jsonb:='[]';candidates jsonb:='[]';current_updates jsonb:='[]';current_judgments jsonb:='[]';note record;fresh jsonb;blocked boolean:=false;view jsonb;delta jsonb;vid uuid;expiry timestamptz:=clock_timestamp()+interval '15 minutes';BEGIN
 SELECT * INTO w FROM v8.work_items WHERE id=ctx.work_item_id;SELECT * INTO pr FROM v8.projects WHERE id=ctx.project_id;
 FOR source IN SELECT * FROM v8.context_sources WHERE context_id=ctx.id LOOP
  IF mem.version_visible((c->>'actor_id')::uuid,source.version_id) THEN
   BEGIN PERFORM mem.assert_version_sources(h,source.version_id,'mem.read');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;CONTINUE;END;
   refs:=refs||jsonb_build_array(jsonb_build_object('material_id',source.material_id,'version_id',source.version_id,'sha256',source.sha256,'role',source.role,'source_stale',mem.version_stale(source.version_id),'artifact_facts',v8.reference_facts(jsonb_build_object('material_id',source.material_id,'version_id',source.version_id,'sha256',source.sha256))));
   IF v8.reference_facts(jsonb_build_object('material_id',source.material_id,'version_id',source.version_id,'sha256',source.sha256))->>'artifact_availability'<>'available' THEN warnings:=warnings||jsonb_build_array(jsonb_build_object('code','fixed_artifact_current_bytes_unavailable','version_id',source.version_id));END IF;IF mem.version_stale(source.version_id) THEN warnings:=warnings||jsonb_build_array(jsonb_build_object('code','source_correction_recorded','version_id',source.version_id,'next_step','agent_judges_old_fixed_applicability_or_recalculates'));END IF;
   SELECT jsonb_build_object('material_id',cv.material_id,'version_id',cv.id,'sha256',cv.sha256) INTO fresh FROM mem.materials m JOIN mem.content_versions cv ON cv.id=m.current_version_id WHERE m.id=source.material_id AND cv.id<>source.version_id AND mem.version_visible((c->>'actor_id')::uuid,cv.id);
   IF fresh IS NOT NULL THEN BEGIN PERFORM mem.assert_version_sources(h,(fresh->>'version_id')::uuid,'mem.read');candidates:=candidates||jsonb_build_array(fresh);EXCEPTION WHEN insufficient_privilege THEN NULL;END;END IF;
  ELSE blocked:=true;END IF;
 END LOOP;
 IF blocked AND mode='complete' THEN RETURN jsonb_build_object('state','rejected','error_code','source_access_required','retained_state','immutable_manifest_preserved','coverage',jsonb_build_object('returned_view','none','host_visible','unknown'),'next_step','use_authorized_clipped_view');END IF;
 FOR note IN SELECT * FROM v8.work_updates WHERE work_item_id=w.id ORDER BY work_revision LOOP IF v8.authorized_statement(h,c,note.payload) THEN current_updates:=current_updates||jsonb_build_array(jsonb_build_object('update_id',note.id,'sha256',note.sha256,'statement',note.payload,'canonical_text',note.canonical_text,'canonical_format','v8.pg-jsonb-key-order-v1'));END IF;END LOOP;
 FOR note IN SELECT * FROM v8.impact_judgments WHERE project_id=ctx.project_id AND (work_item_id=w.id OR context_id=ctx.id) ORDER BY created_at LOOP IF v8.authorized_statement(h,c,note.payload) THEN current_judgments:=current_judgments||jsonb_build_array(jsonb_build_object('judgment_id',note.id,'sha256',note.sha256,'statement',note.payload,'canonical_text',note.canonical_text,'canonical_format','v8.pg-jsonb-key-order-v1'));END IF;END LOOP;
 delta:=jsonb_build_object('context_expired',ctx.expires_at<=clock_timestamp(),'manifest_state',ctx.state,'project_changed',COALESCE((ctx.manifest->>'project_revision')::bigint,0)<>pr.revision OR COALESCE((ctx.manifest->>'project_epoch')::bigint,0)<>pr.epoch,'work_changed',ctx.work_revision<>w.revision,'frozen_work_revision',ctx.work_revision,'current_work_revision',w.revision,'current_project_revision',pr.revision,'fixed_inputs_preserved',true,'new_version_candidates',candidates,'authorized_work_updates',current_updates,'authorized_impact_judgments',current_judgments);
 IF ctx.expires_at<=clock_timestamp() THEN warnings:=warnings||jsonb_build_array(jsonb_build_object('code','authorized_view_automatically_refreshed'));END IF;
 IF ctx.work_revision<>w.revision THEN warnings:=warnings||jsonb_build_array(jsonb_build_object('code','work_revision_changed','next_step','agent_compares_delta_and_chooses_fixed_or_current_basis'));END IF;
 IF COALESCE((ctx.manifest->>'project_revision')::bigint,0)<>pr.revision OR COALESCE((ctx.manifest->>'project_epoch')::bigint,0)<>pr.epoch THEN warnings:=warnings||jsonb_build_array(jsonb_build_object('code','project_scope_changed_current_authority_rechecked'));END IF;
 IF ctx.state<>'current' THEN warnings:=warnings||jsonb_build_array(jsonb_build_object('code','historical_manifest_state','state',ctx.state));END IF;
 IF blocked THEN view:=jsonb_build_object('schema_version','context.v2','context_id',ctx.id,'project_id',ctx.project_id,'work_item_id',w.id,'goal',w.goal,'fixed_refs',refs,'limitations',jsonb_build_array('restricted_sources_and_dependent_narrative_omitted'),'next_steps',jsonb_build_array('continue_with_authorized_fixed_inputs_or_request_authorized_projection'));
 ELSE view:=ctx.manifest||jsonb_build_object('fixed_refs',refs);END IF;
 view:=view||jsonb_build_object('manifest_hash',ctx.sha256,'manifest_canonical_text',CASE WHEN blocked THEN NULL ELSE ctx.canonical_text END,'canonical_format','v8.pg-jsonb-key-order-v1','delta',delta,'warnings',warnings,'view_created_at',clock_timestamp(),'view_expires_at',expiry,'current_work',jsonb_build_object('work_item_id',w.id,'goal',w.goal,'state',w.state,'revision',w.revision),'coverage',jsonb_build_object('manifest','frozen','returned_view',CASE WHEN blocked THEN 'clipped' ELSE 'authorized_frozen_basis' END,'complete',NOT blocked,'host_visible','unknown'));
 PERFORM authz.assert_effect(h);INSERT INTO v8.context_views(context_id,actor_id,client_id,source_context_id,returned_view,coverage,expires_at) VALUES(ctx.id,(c->>'actor_id')::uuid,(c->>'client_id')::uuid,(c->>'source_context_id')::uuid,view,view->'coverage',expiry) RETURNING id INTO vid;
 INSERT INTO v8.work_executions(work_item_id,actor_id,client_id,source_context_id,context_view_id) VALUES(w.id,(c->>'actor_id')::uuid,(c->>'client_id')::uuid,(c->>'source_context_id')::uuid,vid);
 PERFORM v8.emit(c,'context.view_refreshed',vid,1,o,jsonb_build_object('context_id',ctx.id,'coverage',view->'coverage','delta',delta));
 RETURN jsonb_build_object('state','materialized','context_id',ctx.id,'view_id',vid,'returned_view',view,'coverage',view->'coverage','warnings',warnings,'delta',delta,'expires_at',expiry,'manifest_hash',ctx.sha256);
END $$;

CREATE OR REPLACE FUNCTION v8.context_materialize(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;o uuid:=gen_random_uuid();ctx v8.context_manifests;result jsonb; BEGIN IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.context.materialize',d,b);r:=v8.replay(c,'context_materialize',b,d);IF r IS NOT NULL THEN o:=(r->>'operation_id')::uuid;END IF;SELECT * INTO ctx FROM v8.context_manifests WHERE id=(b->>'context_id')::uuid AND project_id=(c->>'project_id')::uuid;IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;result:=v8.render_current_view(h,c,ctx,COALESCE(b->>'mode','clipped'),o);IF r IS NOT NULL THEN RETURN result||jsonb_build_object('operation_id',o,'receipt','current_authorized_read_attempt','retryable',false);END IF;RETURN v8.remember(c,'context_materialize',b,d,o,result); END $$;
GRANT EXECUTE ON FUNCTION v8.context_materialize(uuid,text,text) TO hub2_v8;

CREATE OR REPLACE FUNCTION v8.impact_judge(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;o uuid:=gen_random_uuid();w v8.work_items;ref jsonb;payload jsonb;hash text; BEGIN IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.work.commit',d,b);r:=v8.replay(c,'impact_judge',b,d);IF r IS NOT NULL THEN RETURN r;END IF;IF b->>'work_item_id' IS NOT NULL THEN w:=v8.lock_work(c,(b->>'work_item_id')::uuid);END IF;IF b->>'context_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM v8.context_manifests WHERE id=(b->>'context_id')::uuid AND project_id=(c->>'project_id')::uuid) THEN RAISE EXCEPTION 'context_scope_mismatch' USING ERRCODE='42501';END IF;FOR ref IN SELECT value FROM jsonb_array_elements(COALESCE(b->'evidence','[]')) LOOP PERFORM v8.assert_ref(c,ref);END LOOP;IF b->>'supersedes' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM v8.impact_judgments WHERE id=(b->>'supersedes')::uuid AND project_id=(c->>'project_id')::uuid) THEN RAISE EXCEPTION 'invalid_judgment_correction';END IF;payload:=b-'idempotency_key';hash:=encode(public.digest(v8.canonical_json(payload),'sha256'),'hex');PERFORM authz.assert_effect(h);INSERT INTO v8.impact_judgments(id,project_id,work_item_id,context_id,actor_id,client_id,source_context_id,choice,applicable_scope,reason,payload,canonical_text,sha256,supersedes) VALUES(o,(c->>'project_id')::uuid,w.id,(b->>'context_id')::uuid,(c->>'actor_id')::uuid,(c->>'client_id')::uuid,(c->>'source_context_id')::uuid,b->>'choice',COALESCE(b->'applicable_scope','{}'),b->'reason',payload,v8.canonical_json(payload),hash,(b->>'supersedes')::uuid);PERFORM v8.emit(c,'impact.judged',o,1,o,jsonb_build_object('judgment_hash',hash,'choice',b->>'choice'));RETURN v8.remember(c,'impact_judge',b,d,o,jsonb_build_object('state','recorded','judgment_id',o,'judgment_hash',hash,'fixed_refs',COALESCE(b->'evidence','[]'),'receipt',jsonb_build_object('statement_id',o,'sha256',hash,'semantic_validity','agent_judgment'))); END $$;
GRANT EXECUTE ON FUNCTION v8.impact_judge(uuid,text,text) TO hub2_v8;

CREATE OR REPLACE FUNCTION v8.impact_read(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;o uuid:=gen_random_uuid(); BEGIN IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.work.read',d,b);SELECT COALESCE(jsonb_agg(jsonb_build_object('judgment_id',j.id,'sha256',j.sha256,'canonical_text',j.canonical_text,'canonical_format','v8.pg-jsonb-key-order-v1','statement',j.payload,'supersedes',j.supersedes,'actor_id',j.actor_id,'created_at',j.created_at) ORDER BY j.created_at),'[]') INTO r FROM v8.impact_judgments j WHERE j.project_id=(c->>'project_id')::uuid AND (b->>'work_item_id' IS NULL OR j.work_item_id=(b->>'work_item_id')::uuid) AND (b->>'context_id' IS NULL OR j.context_id=(b->>'context_id')::uuid) AND NOT EXISTS(SELECT 1 FROM jsonb_path_query(j.payload-'properties','$.**.version_id') ref WHERE NOT mem.version_visible((c->>'actor_id')::uuid,(ref #>> '{}')::uuid));PERFORM mem.bind_request_sources(h,r,(c->>'actor_id')::uuid,'v8.work.read');PERFORM authz.assert_effect(h);RETURN jsonb_build_object('state','read','items',r,'coverage','current_authorized_judgments'); END $$;
GRANT EXECUTE ON FUNCTION v8.impact_read(uuid,text,text) TO hub2_v8;

CREATE OR REPLACE FUNCTION v8.handoff_record(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;o uuid:=gen_random_uuid();w v8.work_items;cid uuid;pack jsonb; BEGIN IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.handoff.record',d,b);r:=v8.replay(c,'handoff_record',b,d);IF r IS NOT NULL THEN RETURN r;END IF;w:=v8.lock_work(c,(b->>'work_item_id')::uuid);IF NOT authz.can_read(COALESCE((b->>'to_actor_id')::uuid,(c->>'actor_id')::uuid),w.project_id) THEN RAISE EXCEPTION 'handoff_target_forbidden' USING ERRCODE='42501';END IF;IF b->>'context_id' IS NULL THEN pack:=v8.build_context(h,c,w,COALESCE(b->'context','{}'),o);cid:=(pack->>'context_id')::uuid;ELSE cid:=(b->>'context_id')::uuid;IF NOT EXISTS(SELECT 1 FROM v8.context_manifests WHERE id=cid AND work_item_id=w.id) THEN RAISE EXCEPTION 'context_scope_mismatch' USING ERRCODE='42501';END IF;END IF;PERFORM authz.assert_effect(h);INSERT INTO v8.handoffs(id,work_item_id,context_id,from_actor_id,to_actor_id,from_source_context_id,rationale,next_actions) VALUES(o,w.id,cid,(c->>'actor_id')::uuid,COALESCE((b->>'to_actor_id')::uuid,(c->>'actor_id')::uuid),(c->>'source_context_id')::uuid,COALESCE(b->>'rationale',''),COALESCE(b->'next_actions','[]'));PERFORM v8.emit(c,'handoff.prepared',o,1,o,jsonb_build_object('work_item_id',w.id,'context_id',cid));RETURN v8.remember(c,'handoff_record',b,d,o,jsonb_build_object('state','prepared','handoff_id',o,'context_id',cid,'work_item_id',w.id,'next_step','recipient_reads_current_authorized_view_with_own_identity')); END $$;
GRANT EXECUTE ON FUNCTION v8.handoff_record(uuid,text,text) TO hub2_v8;

CREATE OR REPLACE FUNCTION v8.handoff_accept(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;o uuid:=gen_random_uuid();transfer v8.handoffs;ctx v8.context_manifests;view jsonb;provided uuid;event bigint; BEGIN IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.handoff.record',d,b);r:=v8.replay(c,'handoff_accept',b,d);IF r IS NOT NULL THEN RETURN r;END IF;SELECT handoff.* INTO transfer FROM v8.handoffs handoff JOIN v8.work_items wi ON wi.id=handoff.work_item_id WHERE handoff.id=(b->>'handoff_id')::uuid AND wi.project_id=(c->>'project_id')::uuid AND handoff.to_actor_id=(c->>'actor_id')::uuid FOR UPDATE OF handoff;IF NOT FOUND THEN RAISE EXCEPTION 'handoff_recipient_forbidden' USING ERRCODE='42501';END IF;SELECT * INTO ctx FROM v8.context_manifests WHERE id=transfer.context_id;IF b->>'context_view_id' IS NOT NULL THEN SELECT id INTO provided FROM v8.context_views WHERE id=(b->>'context_view_id')::uuid AND context_id=ctx.id AND actor_id=(c->>'actor_id')::uuid AND client_id=(c->>'client_id')::uuid;IF provided IS NULL THEN RAISE EXCEPTION 'recipient_view_mismatch' USING ERRCODE='42501';END IF;END IF;view:=v8.render_current_view(h,c,ctx,COALESCE(b->>'mode','clipped'),o);IF view->>'state'='rejected' THEN RETURN v8.remember(c,'handoff_accept',b,d,o,view);END IF;PERFORM authz.assert_effect(h);UPDATE v8.handoffs SET state=COALESCE(b->>'state','continued'),to_source_context_id=(c->>'source_context_id')::uuid,event_revision=event_revision+1 WHERE id=transfer.id RETURNING event_revision INTO event;UPDATE v8.context_views SET acknowledged_at=clock_timestamp() WHERE id=(view->>'view_id')::uuid;PERFORM v8.emit(c,'handoff.'||COALESCE(b->>'state','continued'),transfer.id,event,o,jsonb_build_object('work_item_id',transfer.work_item_id,'view_id',view->'view_id'));RETURN v8.remember(c,'handoff_accept',b,d,o,view||jsonb_build_object('state',COALESCE(b->>'state','continued'),'handoff_id',transfer.id,'work_item_id',transfer.work_item_id)); END $$;
GRANT EXECUTE ON FUNCTION v8.handoff_accept(uuid,text,text) TO hub2_v8;
CREATE OR REPLACE FUNCTION v8.work_read(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$
DECLARE b jsonb;c jsonb;r jsonb;w v8.work_items;receipt uuid;blocked boolean:=false;refs jsonb:='[]';rels jsonb:='[]';updates jsonb:='[]';ref jsonb;relation record;note record;basis jsonb;BEGIN
 IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.work.read',d,b);
 SELECT * INTO w FROM v8.work_items WHERE id=(b->>'work_item_id')::uuid AND project_id=(c->>'project_id')::uuid;IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;
 FOR ref IN SELECT jsonb_build_object('material_id',material_id,'version_id',version_id,'sha256',sha256,'role',role) FROM v8.results WHERE work_item_id=w.id LOOP IF v8.authorized_ref(h,c,ref) THEN refs:=refs||jsonb_build_array(ref||jsonb_build_object('artifact_facts',v8.reference_facts(ref)));ELSE blocked:=true;END IF;END LOOP;
 IF NOT v8.authorized_statement(h,c,w.explanation) THEN blocked:=true;END IF;
 FOR relation IN SELECT link.* FROM v8.work_relations link JOIN v8.work_items other ON other.id=CASE WHEN link.from_work_id=w.id THEN link.to_work_id ELSE link.from_work_id END WHERE (link.from_work_id=w.id OR link.to_work_id=w.id) AND authz.can_read((c->>'actor_id')::uuid,other.project_id) AND NOT EXISTS(SELECT 1 FROM v8.work_relations newer WHERE newer.supersedes=link.id) LOOP
  basis:=CASE WHEN blocked OR NOT v8.authorized_statement(h,c,relation.basis) THEN NULL ELSE relation.basis END;
  rels:=rels||jsonb_build_array(jsonb_build_object('id',relation.id,'from_work_id',relation.from_work_id,'to_work_id',relation.to_work_id,'state',relation.state,'supersedes',relation.supersedes,'basis',basis));END LOOP;
 FOR note IN SELECT * FROM v8.work_updates WHERE work_item_id=w.id ORDER BY work_revision LOOP IF v8.authorized_statement(h,c,note.payload) THEN updates:=updates||jsonb_build_array(jsonb_build_object('update_id',note.id,'sha256',note.sha256,'canonical_text',note.canonical_text,'canonical_format','v8.pg-jsonb-key-order-v1','work_revision',note.work_revision,'statement',note.payload,'actor_id',note.actor_id));END IF;END LOOP;
 PERFORM authz.assert_effect(h);INSERT INTO v8.work_read_receipts(work_item_id,work_revision,actor_id,client_id,source_context_id) VALUES(w.id,w.revision,(c->>'actor_id')::uuid,(c->>'client_id')::uuid,(c->>'source_context_id')::uuid) RETURNING id INTO receipt;
 PERFORM authz.assert_effect(h);RETURN jsonb_build_object('updates',updates,'state','read','work_item',CASE WHEN blocked THEN to_jsonb(w)-'explanation'-'description' ELSE to_jsonb(w) END,'read_receipt_id',receipt,'relations',rels,'fixed_refs',refs,'coverage',jsonb_build_object('complete',NOT blocked,'host_visible','unknown'));
END $$;

CREATE OR REPLACE FUNCTION v8.experience_publish(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$
DECLARE b jsonb; c jsonb; r jsonb; o uuid:=gen_random_uuid(); w v8.work_items;prior v8.experiences;ref jsonb;item jsonb;
BEGIN IF encode(public.digest(p,'sha256'),'hex')<>d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.experience.publish',d,b);
r:=v8.replay(c,'experience_publish',b,d);IF r IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN r;END IF;w:=v8.lock_work(c,(b->>'work_item_id')::uuid);
 ref:=b->'fixed_ref';PERFORM v8.assert_ref(c,ref);
 FOR item IN SELECT value FROM jsonb_array_elements(COALESCE(b->'evidence','[]')) LOOP PERFORM v8.assert_ref(c,item);END LOOP;
 IF b ? 'supersedes' THEN SELECT ex.* INTO prior FROM v8.experiences ex JOIN v8.work_items ww ON ww.id=ex.work_item_id WHERE ex.id=(b->>'supersedes')::uuid AND ww.project_id=w.project_id FOR UPDATE OF ex;IF NOT FOUND THEN RAISE EXCEPTION 'invalid_experience_correction';END IF;PERFORM authz.assert_effect(h);UPDATE v8.experiences SET state='superseded',event_revision=event_revision+1 WHERE id=prior.id RETURNING * INTO prior;PERFORM v8.emit(c,'experience.superseded',prior.id,prior.event_revision,o,jsonb_build_object('replacement_id',o));END IF;
 PERFORM authz.assert_effect(h);INSERT INTO v8.experiences(id,work_item_id,material_id,version_id,sha256,conditions,evidence,state,revision,supersedes,actor_id) VALUES(o,w.id,(ref->>'material_id')::uuid,(ref->>'version_id')::uuid,ref->>'sha256',COALESCE(b->'conditions','{}'),COALESCE(b->'evidence','[]'),COALESCE(b->>'state','published'),COALESCE(prior.revision,0)+1,prior.id,(c->>'actor_id')::uuid);
 PERFORM v8.emit(c,'experience.published',o,1,o,jsonb_build_object('work_item_id',w.id,'supersedes',prior.id));PERFORM authz.assert_effect(h);RETURN v8.remember(c,'experience_publish',b,d,o,jsonb_build_object('state',COALESCE(b->>'state','published'),'experience_id',o,'fixed_refs',jsonb_build_array(ref),'domain_revision',COALESCE(prior.revision,0)+1,'coverage','publisher_claim_with_fixed_evidence'));
END $$;

CREATE OR REPLACE FUNCTION v8.adoption_read(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb; BEGIN IF encode(public.digest(p,'sha256'),'hex')<>d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.adoption.read',d,b);SELECT COALESCE(jsonb_agg(jsonb_build_object('adoption_id',a.id,'material_id',a.material_id,'version_id',a.version_id,'sha256',a.sha256,'role',a.role,'reason',a.reason,'revision',a.revision,'supersedes',a.supersedes,'use_evidence',a.use_evidence)),'[]') INTO r FROM v8.adoptions a JOIN v8.work_items w ON w.id=a.work_item_id WHERE w.id=(b->>'work_item_id')::uuid AND w.project_id=(c->>'project_id')::uuid AND mem.version_visible((c->>'actor_id')::uuid,a.version_id);PERFORM mem.bind_request_sources(h,jsonb_build_object('fixed_refs',r),(c->>'actor_id')::uuid,'v8.adoption.read');PERFORM authz.assert_effect(h);PERFORM authz.assert_effect(h);RETURN jsonb_build_object('state','read','adoptions',r,'coverage','current_authorized_fixed_history'); END $$;
GRANT EXECUTE ON FUNCTION v8.adoption_read(uuid,text,text) TO hub2_v8;

CREATE OR REPLACE FUNCTION v8.operation_read(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;ref jsonb;restricted boolean:=false;BEGIN IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.work.read',d,b);SELECT result INTO r FROM v8.operations WHERE id=(b->>'operation_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid;IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;FOR ref IN SELECT value FROM v8.ref_inputs(r) AS input(value) LOOP IF NOT v8.authorized_ref(h,c,ref) THEN restricted:=true;END IF;END LOOP;IF restricted THEN r:=jsonb_build_object('operation_id',r->'operation_id','state',r->'state','domain_revision',r->'domain_revision','retained_state','receipt_and_candidate_preserved_sources_currently_restricted','coverage',jsonb_build_object('returned_view','restricted_metadata','host_visible','unknown'),'next_step','recover_with_current_authorized_inputs');END IF;PERFORM authz.assert_effect(h);RETURN r;END $$;
CREATE OR REPLACE FUNCTION v8.context_read(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;r jsonb;ctx v8.context_manifests; BEGIN IF encode(public.digest(p,'sha256'),'hex')<>d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.context.read',d,b);SELECT * INTO ctx FROM v8.context_manifests WHERE id=(b->>'context_id')::uuid AND project_id=(c->>'project_id')::uuid;IF NOT FOUND OR EXISTS(SELECT 1 FROM v8.context_sources WHERE context_id=ctx.id AND NOT mem.version_visible((c->>'actor_id')::uuid,version_id)) THEN RAISE EXCEPTION 'history_source_forbidden' USING ERRCODE='42501';END IF;PERFORM authz.assert_effect(h);PERFORM authz.assert_effect(h);RETURN jsonb_build_object('state','historical','context_id',ctx.id,'manifest_hash',ctx.sha256,'manifest_canonical_text',ctx.canonical_text,'canonical_format','v8.pg-jsonb-key-order-v1','returned_view',ctx.manifest,'coverage',jsonb_build_object('manifest','immutable_history','host_visible','unknown'),'next_step','prepare_fresh_context_before_continuation'); END $$;
GRANT EXECUTE ON FUNCTION v8.context_read(uuid,text,text) TO hub2_v8;
CREATE FUNCTION v8.work_history(h uuid,d text,p text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,v8 AS $$ DECLARE b jsonb;c jsonb;history jsonb:='[]';entry record;BEGIN IF p IS NULL OR d IS NULL OR encode(public.digest(p,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;b:=p::jsonb;c:=v8.guard(h,'v8.work.read',d,b);FOR entry IN SELECT snapshot.* FROM v8.work_snapshots snapshot JOIN v8.work_items work ON work.id=snapshot.work_item_id WHERE work.id=(b->>'work_item_id')::uuid AND work.project_id=(c->>'project_id')::uuid ORDER BY snapshot.work_revision LOOP IF v8.authorized_statement(h,c,entry.record) THEN history:=history||jsonb_build_array(jsonb_build_object('snapshot_id',entry.id,'work_revision',entry.work_revision,'record',entry.record,'sha256',entry.sha256,'canonical_text',entry.canonical_text,'canonical_format','v8.pg-jsonb-key-order-v1'));END IF;END LOOP;PERFORM authz.assert_effect(h);RETURN jsonb_build_object('state','historical','items',history,'coverage','current_authorized_fixed_work_revisions');END $$;
GRANT EXECUTE ON FUNCTION v8.work_history(uuid,text,text) TO hub2_v8;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA v8 FROM PUBLIC;
RESET ROLE;
